+            if (false == item.keySet().containsAll(matchers.keySet())) {
+                return false;
+            }
+        } else {
+            if (false == item.keySet().equals(matchers.keySet())) {
+                return false;
+            }
+        }
+        for (Map.Entry<Object, Matcher<?>> e : matchers.entrySet()) {
+            if (false == item.containsKey(e.getKey())) {
+                return false;
+            }
